				B.add(mat.bark, tw.g);
				const tc = {
					x: tw.tip[0],
					y: tw.tip[1] + .5,
					z: tw.tip[2],
					R: 1.8,
					Rv: 1.4
				};
				B.add(mat.leaves, foliage(tw.tip[0], tw.tip[1] + .55, tw.tip[2], 1.05 + rng() * .4, rng, 2, tc, tint));
