        vFade = smoothstep(3.0, 12.0, -mv.z) * (1.0 - smoothstep(0.6, 0.95, endOn)) * (0.75 + 0.25 * sin(uTime * 0.5 + size.z));
        gl_Position = projectionMatrix * mv;
