var SIGN_TEXT = [
	"茶屋",
	"団子",
	"本屋",
	"武器",
	"薬",
	"宿"
];
async function buildArena(map, { grass = 26e3 } = {}) {
	try {
		await Promise.all(["64px \"Yuji Syuku\"", "64px \"Kaushan Script\""].map((f) => document.fonts.load(f)));
	} catch {}
	const P = {
		grass: Paint.grass(),
		dirt: Paint.dirt(),
		bark: Paint.bark(),
		rock: Paint.rock(),
		plaster: Paint.plaster(),
		timber: Paint.wood(6),
		woodLight: Paint.wood(16, true),
		tiles: Paint.tiles(7, 6110007),
		tiles2: Paint.tiles(17, 4082268),
		stone: Paint.stone(),
		leaves: Paint.leaves(),
		chain: Paint.chainlink(),
		shoji: Paint.shoji(),
		crate: Paint.crate()
	};
	TOON.uHatch.value = Paint.hatch();
	const mat = {
		bark: toon({
			map: P.bark,
			tri: .32,
			hatch: .95,
			vertexColors: true
		}),
		leaves: toon({
			map: P.leaves,
			tri: .2,
			hatch: .35,
			vertexColors: true,
			near: true
		}),
		rock: toon({
			map: P.rock,
			tri: .09,
			hatch: .85
		}),
		grassCap: toon({
			map: P.grass,
			tri: .18,
			hatch: .5
		}),
		woodCut: toon({
			color: 14266492,
			hatch: .3
		}),
		chain: toon({
			map: P.chain,
			alphaTest: .5,
			side: 2,
			hatch: .2,
			fade: false
		}),
		rust: toon({
			color: 8014384,
			hatch: .6
		}),
		woodLight: toon({
			map: P.woodLight,
			tri: .55,
			hatch: .6
		}),
		rope: toon({
			color: 14272928,
			hatch: .3
		}),
		memorial: toon({
			map: P.stone,
			tri: .35,
			color: 12170952,
			hatch: .7
		}),
		stone: toon({
			map: P.stone,
			tri: .45,
			hatch: .7
		}),
		stoneWall: toon({
			map: P.stone,
			tri: .35,
			hatch: .8
		}),
		target: toon({
			map: Paint.target(),
			hatch: .2
		}),
		plaster: toon({
			map: P.plaster,
			tri: .3,
			hatch: .75
		}),
		timber: toon({
			map: P.timber,
			tri: .7,
			hatch: .8
		}),
		interior: toon({
			color: 2826009,
			hatch: 0
		}),
		shoji: toon({
			map: P.shoji,
			hatch: .3
		}),
		noren: toon({
			map: Paint.noren("一楽"),
			side: 2,
			hatch: .3
		}),
		ramenSign: toon({
			map: Paint.sign("ラーメン", {
				w: 512,
				h: 170,
				size: 120
			}),
			hatch: .1
		}),
		signs: SIGN_TEXT.map((t, i) => toon({
			map: Paint.sign(t, {
				w: 96,
				h: 300,
				size: 76,
				vertical: true,
				bg: [
					"#f1e6c8",
					"#2b2b30",
					"#b3261e"
				][i % 3],
				fg: [
					"#2b1d12",
					"#f1e6c8",
					"#fff4dc"
				][i % 3]
			}),
			hatch: .1
		})),
		awnRed: toon({
			map: Paint.stripes("#c0342a"),
			side: 2,
			hatch: .5
		}),
		awnYellow: toon({
			map: Paint.stripes("#e0a82a"),
			side: 2,
			hatch: .5
		}),
		roof: toon({
			map: P.tiles,
			hatch: .6
		}),
		roofRidge: toon({
			color: 3811108,
			hatch: .5
		}),
		pot: toon({
			color: 10638638,
			hatch: .5
		}),
		bush: toon({
			map: P.leaves,
			tri: .6,
			hatch: .4
		}),
		crate: toon({
			map: P.crate,
			hatch: .5
		}),
		lanternRed: toon({
			color: 16738884,
			emissive: 16727060,
			hatch: 0
		}),
		lanternWhite: toon({
			color: 16773848,
			emissive: 16763024,
			hatch: 0
		}),
		water: waterMaterial()
	};
	mat.lanternRed.emissiveIntensity = 2.6;
	mat.lanternWhite.emissiveIntensity = 1.8;
	mat.water.userData.noShadow = true;
	mat.chain.userData.noShadow = false;
	const group = new Group();
	group.name = "arena";
	group.add(buildTerrain(map, P));
	const B = new Batch();
	buildTrees(map, B, mat);
	buildCliffs(map, B, mat);
	buildRocks(map, B, mat);
	buildLogs(map, B, mat);
	buildFences(map, B, mat);
	buildField(map, B, mat);
	const lanterns = buildVillage(map, B, mat, Paint);
	buildBridge(map, B, mat);
	B.build(group);
	group.add(buildLanterns(lanterns, mat));
	const river = buildRiver(map, mat);
	group.add(river);
	const shafts = buildShafts(map, SUN_DIR);
	group.add(shafts);
	const leaves = buildLeaves();
	group.add(leaves);
	const grassMesh = grass > 0 ? buildGrass(map, grass) : null;
	if (grassMesh) group.add(grassMesh);
	return {
		group,
		mat,
		textures: [...Object.values(P), TOON.uHatch.value],
		fall: river.userData.fall,
		grass: grassMesh,
		update(dt, fx) {
			mat.water.uniforms.uTime.value += dt;
			shafts.userData.mat.uniforms.uTime.value += dt;
			leaves.userData.mat.uniforms.uTime.value += dt;
			if (grassMesh) grassMesh.userData.wind.value += dt;
			const f = river.userData.fall;
			if (f && fx && Math.random() < dt * 30) fx.emit(0, f.x + (Math.random() - .5) * f.w, f.y + .2, f.z, (Math.random() - .5) * 1.5, 1.2, 1 + Math.random(), .7, .3, 1.1, .95, .98, 1, .8);
		}
	};
}
