/** The same upper-body keys hanging in the air: legs tucked, the body pitched so the torrent angles down. */
function airVariant(def, pitch) {
	const AIR = {
		h: [
			0,
			.05,
			0
		],
		lf: {
			p: [
				.12,
				.3,
				.2
			],
			pole: [
				0,
				.3,
				1
			],
			pitch: 20
		},
		rf: {
			p: [
				-.12,
				.18,
				-.15
			],
			pole: [
				0,
				.3,
				1
			],
			pitch: 30
		}
	};
	return {
		base: AIR,
		keys: def.keys.map(([f, s, e]) => {
			if (!Object.keys(s).length) return [
				f,
				s,
				e
			];
			const o = {
				...s,
				lf: AIR.lf,
				rf: AIR.rf,
				h: [
					0,
					.05,
					0
				]
			};
			if (f >= 26) {
				o.neck = [
					(s.neck?.[0] || 0) + pitch * .5,
					s.neck?.[1] || 0,
					0
				];
				o.head = [
					(s.head?.[0] || 0) + pitch * .5,
					s.head?.[1] || 0,
					0
				];
			}
			return [
				f,
				o,
				e
			];
		})
	};
}
